void CanMain_InitMemory( uint8 LeCanMain_u_Src )
{
    switch(LeCanMain_u_Src)
    {
        case 0u:
        {
            (void)FLEXCAN_DRV_Init(flexcanInitConfig0_INST,&flexcanInitConfig0_State,&flexcanInitConfig0);
            CanMain_AllModuInit();
            break;
        }
        case 1u:
        {
            CanMain_AllVarInit();
            break;
        }
        default:
        {
            CanMain_AllModuInit();
            break;
        }
    }
    CanMain_IntEnableIRQFunction();
}
