void CanMain_5msBMainFunction( void )
{

    CanTrcv_MainFunction();
    Ccl_5_0msTaskCont();
    CanApp_MainFunction();
    
	
	//  ggl 2025/12/11
	if(CanDem_DcmGet_NetDtc_EnableConditionStatus() == 0u)
	{
		SeCanMain_u_StartRxTimeout = 0;
	}
    else if((CanDem_DcmGet_NetDtc_EnableConditionStatus() == 1u) && (SeCanMain_u_StartRxTimeout == 0U) )
    {
		IlRxStop();
		IlRxStart();
		SetCanApp_ClearTimeOut();
		SeCanMain_u_StartRxTimeout = 1U;
    }
    else
	{
    	
    }
}

