void CanMain_20msMainFunction(void)
{
	CanDem_MainFunction20ms();
    //CDiagUart_MainFunction();
    if(SeCanMain_u_Start5SFlag == 0u)
    {
        SeCanMain_u_5SCount --;
        if(SeCanMain_u_5SCount == 0u)
        {
            SeCanMain_u_Start5SFlag = 1u;
            if(SeCanMain_u_ResetFlag == 1)
            {
                SystemSoftwareReset();
                
            }
        }
    }
    
}



