static void CanMain_IntEnableIRQFunction( void )
{
    INT_SYS_InstallHandler(CAN1_Error_IRQn, &CanMailboxIsr_01111111111, (isr_t *)0);
    INT_SYS_InstallHandler(CAN1_ORed_0_15_MB_IRQn, &CanMailboxIsr_0, (isr_t *)0);
    INT_SYS_InstallHandler(CAN1_ORed_16_31_MB_IRQn, &CanMailboxIsr_0, (isr_t *)0);
    INT_SYS_InstallHandler(CAN1_ORed_IRQn, &CanBusOffIsr_0, (isr_t *)0);
    INT_SYS_EnableIRQ(CAN1_Error_IRQn);
    INT_SYS_EnableIRQ(CAN1_ORed_0_15_MB_IRQn);
    INT_SYS_EnableIRQ(CAN1_ORed_16_31_MB_IRQn);
    INT_SYS_EnableIRQ(CAN1_ORed_IRQn);
}

